from __future__ import annotations; from pathlib import Path; from common.meta.extension.check_package_contract import check_single_package, discover_packages; REPO = Path(__file__).resolve().parents[2]; TESTING = REPO / 'common' / 'testing'
def test_AC_testing_1_1_only_all_is_the_published_language(): import common.testing as testing_pkg; from common.testing.contract import CONTRACT; assert sorted(CONTRACT.interface) == sorted(testing_pkg.__all__); assert CONTRACT.name == 'testing'; assert CONTRACT.klass == 'infra'; assert CONTRACT.implementations['be'] == 'common/testing'
def test_AC_testing_1_1_package_contract_gate_passes_for_testing(): names = {p.name for p in discover_packages(REPO)}; assert 'testing' in names, f'testing not discovered; found {names}'; ok, messages = check_single_package('testing', REPO); assert ok, 'package contract gate failed:\n' + '\n'.join(messages)
